<template>
  <div class="equipment-type-container" ref="fullRef">

    <!-- 头部菜单 - 开始 -->
    <div ref="headerRef">
      <el-row>
        <!-- 搜索框 - 开始 -->
        <el-col :span="18" @keyup.enter.native="handleSearch">
          <el-form inline class="query-form" label-width="5em">
            <el-form-item label="标准名称">
              <el-input v-model="searchVIewParam.standardName" maxlength="100" placeholder="请输入标准名称"/>
            </el-form-item>
            <el-form-item label="创建日期">
              <el-date-picker v-model="searchVIewParam.beginTime" type="date" placeholder="开始日期" value-format="yyyy-MM-dd"/>
              <span style="margin: 0 5px">至</span>
              <el-date-picker v-model="searchVIewParam.endTime" type="date" placeholder="结束日期" value-format="yyyy-MM-dd"/>
            </el-form-item>
            <el-form-item label="创建人">
              <el-input v-model="searchVIewParam.createUser" maxlength="100" placeholder="请输入创建人"/>
            </el-form-item>
          </el-form>
        </el-col>
        <!-- 搜索框 - 结束 -->
        <!-- 按钮 - 开始 -->
        <el-col :span="6">
          <el-form inline style="text-align: right">
            <el-form-item>
              <el-button type="primary" @click="handleSearch">查询</el-button>
            </el-form-item>
            <el-form-item>
              <el-button type="info"    @click="handleResetSearch">重置</el-button>
            </el-form-item>
            <el-form-item>
              <el-button type="success" @click="handleShowDialog('add')">新增</el-button>
            </el-form-item>
          </el-form>
        </el-col>
        <!-- 按钮 - 结束 -->
      </el-row>
    </div>
    <!-- 头部菜单 - 结束 -->

    <!-- 表格 - 开始 -->
    <el-table :data="tableStandardData" border style="width: 100%; margin-top: 20px" :max-height="tableHeight" :key="tableHeight">
      <el-table-column type="index" label="序号" align="center">
        <template slot-scope="scope">
          {{ (currentPage - 1) * pageSize + scope.$index + 1 }}
        </template>
      </el-table-column>
      <el-table-column prop="standardName"        label="标准名称" show-overflow-tooltip/>
      <el-table-column prop="standardDescription" label="标准描述" show-overflow-tooltip/>
      <el-table-column prop="createTime"          label="创建日期" show-overflow-tooltip/>
      <el-table-column prop="updateTime"          label="修改日期" show-overflow-tooltip/>
      <el-table-column prop="createUser"          label="创建人"   show-overflow-tooltip/>
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button type="primary" @click="handleShowDialog('edit', scope.row)">编辑</el-button>
          <el-button type="danger"  @click="handleDelete(scope.row)">删除</el-button>
        </template>
      </el-table-column>
    </el-table>
    <!-- 表格 - 结束 -->

    <div ref="footerRef">
      <!-- 分页区域 -->
      <el-pagination
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
        :current-page="currentPage"
        :page-sizes="[10, 20, 30, 40]"
        :page-size="pageSize"
        layout="total, sizes, prev, pager, next, jumper"
        :total="total"
        style="margin-top: 20px; text-align: center"
      >
      </el-pagination>
    </div>

    <!-- 对话框 - 开始 -->
    <el-dialog style="min-width: 500px;" :title="dialogTitle" :visible.sync="dialogVisible" @close="handleResetDialog" :close-on-click-modal="false">
      <!-- 新增/编辑 - 开始 -->
      <div v-show="dialogVisible && ['add', 'edit'].includes(dialogType)">
        <el-form :model="dialogForm" :rules="dialogRules" ref="dialogFormRef" label-width="6em" min-width="300px">
          <el-form-item label="标准名称" prop="standardName">
            <el-input v-model="dialogForm.standardName" maxlength="100" placeholder="请输入标准名称"/>
          </el-form-item>
          <el-form-item label="标准描述" prop="standardDescription">
            <el-input v-model="dialogForm.standardDescription" maxlength="500" placeholder="请输入标准描述"/>
          </el-form-item>
          <el-form-item prop="standardDeviceData">
            <el-button type="primary" @click="handleChangeDialog">+ 添 加 设 备 </el-button>
          </el-form-item>
        </el-form>
        <el-table :data="dialogForm.standardDeviceData" border style="width: 100%;" height="50vh">
          <el-table-column type="index" label="序号" align="center"/>
          <el-table-column prop="deviceCode"    label="设备编码" show-overflow-tooltip/>
          <el-table-column prop="deviceName"    label="设备名称" show-overflow-tooltip/>
          <el-table-column prop="deviceType"    label="设备类型" show-overflow-tooltip>
            <template slot-scope="scope">
              {{ getCategoryName(scope.row.parentId, scope.row.childId) }}
            </template>
          </el-table-column>
          <el-table-column prop="standardCount" label="标准数量">
            <template slot-scope="scope">
              <el-input-number v-model="scope.row.standardCount" :key="scope.row.id" controls-position="right" :min="0" :max="2000000000"/>
            </template>
          </el-table-column>
          <el-table-column label="操作" align="center">
            <template slot-scope="scope">
              <el-button type="danger"  @click="handleDialogDelete(scope.$index)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
      </div>
      <!-- 新增/编辑 - 结束 -->
      <!-- 添加设备 - 开始 -->
      <div v-if="dialogVisible && dialogType == 'device'">
        <el-row>
          <!-- 搜索框 - 开始 -->
          <el-col :span="18">
            <el-form inline class="query-form" label-width="5em">
              <el-form-item label="设备名称">
                <el-input v-model="dialogSearchViewParam.deviceName" maxlength="100" placeholder="请输入设备名称"/>
              </el-form-item>
              <!-- <el-form-item label="设备分类">
                <el-cascader
                  placeholder="请选择分类名称"
                  :options="categoryList"
                  v-model="selectedCategory"
                  :props="{ checkStrictly: true }"
                  clearable
                  filterable>
                </el-cascader>
              </el-form-item> -->
            </el-form>
          </el-col>
          <!-- 搜索框 - 结束 -->
          <!-- 按钮 - 开始 -->
          <el-col :span="6">
            <el-form inline style="text-align: right">
              <el-form-item>
                <el-button type="primary" @click="handleDialogSearch">查询</el-button>
              </el-form-item>
              <el-form-item>
                <el-button type="info"    @click="handleDialogReset">重置</el-button>
              </el-form-item>
            </el-form>
          </el-col>
          <!-- 按钮 - 结束 -->
        </el-row>

        <!-- 表格区域 -->
        <el-table :data="dialogTableData" border style="width: 100%; margin-top: 20px" row-key="id" :tree-props="{ children: 'children', hasChildren: 'hasChildren' }" stripe>
          >
          <el-table-column prop="deviceCode" label="设备编码" align="center"/>
          <el-table-column prop="deviceName" label="设备名称" align="center"/>
          <el-table-column label="设备分类" align="center">
            <template slot-scope="scope">
              {{ getCategoryName(scope.row.parentId, scope.row.childId) }}
            </template>
          </el-table-column>
          <el-table-column prop="deviceDescription" label="设备描述" align="center"/>
          <el-table-column label="操作" align="center">
            <template slot-scope="scope">
              <el-button type="primary" @click="handleDialogAdd(scope.row)" :disabled="scope.row.disabled">{{ scope.row.disabled ? '已添加' : '添&emsp;加' }}</el-button>
            </template>
          </el-table-column>
        </el-table>

        <!-- 分页区域 -->
        <el-pagination
          @size-change="handleDialogSizeChange"
          @current-change="handleDialogCurrentChange"
          :current-page="dialogCurrentPage"
          :page-sizes="[5, 10]"
          :page-size="dialogPageSize"
          layout="total, sizes, prev, pager, next, jumper"
          :total="dialogTotal"
          style="margin-top: 20px; text-align: center"
        >
        </el-pagination>
      </div>
      <!-- 添加设备 - 结束 -->
      <div slot="footer">
        <el-button type="primary" @click="handleSubmit" @loading="loading" v-if="dialogType != 'device'">保 存</el-button>
        <el-button type="danger"  @click="handleResetDialog" @loading="loading" v-if="dialogType != 'device'">取 消</el-button>
        <el-button type="primary" @click="handleReturn" v-if="dialogType == 'device'">返 回</el-button>
      </div>
    </el-dialog>
    <!-- 对话框 - 结束 -->
  </div>
</template>

<script>
import request from "@/utils/request.js"
export default {
  data() {
    return {
    // 头部菜单
      searchVIewParam: {
        standardName: '',
        beginTime: '',
        endTime: '',
        createUser: '',
      },                              // 查询参数（页面）
      searchRequestParam: {},         // 查询参数（请求）

    // 表格
      tableStandardData: [],          // 表格数据
      tableHeight: 500,               // 表格最大高度默认值
      pageSize: 10,                   // 表格数据条数
      total: 50,                      // 表格数据总数
      currentPage: 1,                 // 表格当前页码

    // 对话框
      dialogTitle: '',                // 对话框标题
      dialogVisible: false,           // 对话框是否显示
      dialogType: '',                 // 对话框类型(add - 新增；edit - 编辑；device - 添加设备；)
      dialogForm: {
        id: '',
        standardName: '',
        standardDescription: '',
        createUser: '测试用户',
        standardDeviceData: [],       // 表格数据
      },                              // 对话框表单的值
      dialogRules: {
        standardName: [
          { required: true, message: '请输入活动名称', trigger: 'blur' },
          { min: 1, max: 25, message: '长度在1-25个字符', trigger: 'blur' }
        ],
        standardDeviceData: [
          { required: true, message: '请添加设备', trigger: 'blur' }
        ],
      },                              // 对话框表单校验规则
      dialogSearchViewParam: {
        deviceName: '',
      },                              // 对话框（添加设备）查询参数（页面）
      dialogSearchRequestParam: {
        deviceName: '',
      },                              // 对话框（添加设备）查询参数（请求）
      dialogTableData: [],            // 对话框（添加设备）表格数据
      dialogCurrentPage: 1,           // 对话框（添加设备）表格当前页码
      dialogPageSize: 5,              // 对话框（添加设备）表格数据条数
      dialogTotal: 50,                // 对话框（添加设备）表格数据总数
      categoryList: [],               // 设备分类列表
      loading: false,                 // 请求是否完成

    }
  },

  created() {
    // 获取表格数据
    this.sendSearch()
  },

  mounted() {
    // 监听页面尺寸变化
    window.addEventListener('resize', this.getTableHeight)
    this.getTableHeight()
  },

  beforeDestroy() {
    // 关闭监听
    window.removeEventListener('resize', this.getTableHeight)
  },

  methods: {
// 头部菜单
    // 点击查询
    handleSearch() {
      this.currentPage = 1
      this.searchRequestParam = { ...this.searchVIewParam }
      this.sendSearch()
    },

    // 重置查询参数并查询
    handleResetSearch() {
      this.searchVIewParam = {
        standardName: '',
        beginTime: '',
        endTime: '',
        createUser: '',
      }
      // 重新查询
      this.handleSearch()
    },


// 表格
    // 点击删除
    handleDelete(row) {
      this.$confirm("此操作将删除标准：" + row.standardName + ", 是否继续?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
      .then(() => {
        this.sendDelete(row)
      })
      .catch(() => {
        this.$message.info("已取消删除")
      })
    },

    // 每页条数改变
    handleSizeChange(val) {
      this.pageSize = val
      this.currentPage = 1
      this.sendSearch()
    },

    // 翻页
    handleCurrentChange(val) {
      this.currentPage = val
      this.sendSearch()
    },


// 对话框
    // 打开对话框
    handleShowDialog(type, row) {
      switch (type) {
        case 'add':
          this.dialogTitle = '标准新增'
          break
        case 'edit':
          this.dialogTitle = '编辑设备标准：' + row.standardName
          this.dialogForm = {
            id: row.id,
            standardName: row.standardName,
            standardDescription: row.standardDescription,
            createUser: '测试用户',
            standardDeviceData: []
          }
          // 获取已添加设备
          this.sendGetStandardDevice(row.id)
          break
      }
      this.dialogType = type
      this.dialogVisible = true
    },

    // 切换对话框至添加设备
    handleChangeDialog() {
      this.dialogType = 'device'
      this.handleDialogSearch()
    },

    // 返回添加/编辑对话框
    handleReturn() {
      if (this.dialogTitle == '标准新增') this.dialogType = 'add'
      else this.dialogType = 'edit'
      this.dialogSearchViewParam = {
        deviceName: '',
      }
      this.dialogTableData = []
    },

    // 移除选中的设备
    handleDialogDelete(index) {
      this.dialogForm.standardDeviceData.splice(index, 1)
    },

    // 查询设备
    handleDialogSearch() {
      this.dialogCurrentPage = 1
      this.$set(this.dialogSearchRequestParam, 'deviceName', this.dialogSearchViewParam.deviceName)
      this.sendSearchDevice()
    },

    // 重置查询参数
    handleDialogReset() {
      this.dialogSearchViewParam = {
        deviceName: '',
      }
      this.handleDialogSearch()
    },

    // 添加设备
    handleDialogAdd(row) {
      this.dialogForm.standardDeviceData.push(row)
      this.$message.success('添加成功')
      this.sendSearchDevice()
    },

    // 翻页
    handleDialogCurrentChange(val) {
      this.dialogCurrentPage = val
      this.sendSearchDevice()
    },

    // 每页条数改变
    handleDialogSizeChange(val) {
      this.dialogPageSize = val
      this.dialogCurrentPage = 1
      this.sendSearchDevice()
    },

    // 提交
    handleSubmit() {
      this.$refs['dialogFormRef'].validate(valid => {
        if (!valid) return
        if (this.dialogType == 'add') {
          // 发送新增请求
          this.sendSubmitAdd()
        } else if (this.dialogType == 'edit') {
          // 发送编辑请求
          this.sendSubmitEdit()
        }
      })      
    },

    // 关闭弹窗并清空校验和参数
    handleResetDialog() {
      this.dialogForm = {
        id: '',
        standardName: '',
        standardDescription: '',
        createUser: '测试用户',
        standardDeviceData: [],
      }
      this.dialogVisible = false
      this.dialogType = ''
      this.dialogSearchViewParam = {
        deviceName: '',
      }
      this.dialogTableData = []
      this.dialogCurrentPage = 1
      this.dialogPageSize = 5
      this.dialogTotal = 50
      this.$refs.dialogFormRef.clearValidate()
    },


// 请求
    // 查询表格数据
    sendSearch() {
      request.post('deviceStandard/searchByCondition', {
        queryParam: this.searchRequestParam,
        pageNum: this.currentPage,
        pageSize: this.pageSize,
      })
      .then(res => {
        if (res && res.code == 200) {
          this.tableStandardData = res.data.data
          this.total = res.data.total
          this.currentPage = res.data.pageNum
          this.pageSize = res.data.pageSize
        } else {
          this.$message.warning(res.message)
        }
      })
    },

    // 获取标准中的设备
    sendGetStandardDevice(id) {
      request.post('deviceStandard/getStandardDevice', id)
      .then(res => {
        if (res && res.code == 200) {
          this.dialogForm.standardDeviceData = res.data
          console.log(this.dialogForm)
        } else {
          this.$message.warning(res.message)
        }
      })
    },

    // 提交新增
    sendSubmitAdd() {
      this.loading = true
      request.post('deviceStandard/addStandard', this.dialogForm)
      .then(res => {
        if (res && res.code == 200) {
          this.$message.success('设备标准新增成功')
          // 关闭对话框
          this.handleResetDialog()
          // 刷新表格数据
          this.handleResetSearch()
        } else {
          this.$message.warning(res.message)
        }
        this.loading = false
      })
      .catch(() => {
        this.loading = false
      })
    },

    // 提交编辑
    sendSubmitEdit() {
      this.loading = true
      request.post('deviceStandard/editStandard', this.dialogForm)
      .then(res => {
        if (res && res.code == 200) {
          this.$message.success("设备标准编辑成功")
          // 关闭对话框
          this.handleResetDialog()
          // 重新查询当前页表格数据
          this.sendSearch()
        } else {
          this.$message.warning(res.message)
        }
        this.loading = false
      })
      .catch(() => {
        this.loading = false
      })
    },

    // 提交删除
    sendDelete(row) {
      request.post('deviceStandard/deleteStandard', row.id
      )
      .then(res => {
        if (res && res.code == 200) {
          this.$message.success('标准：' + row.standardName + "删除成功！")
          // 如果删除的是页面中最后一条
          // if () {

          // }
          // 重新查询当前页表格数据
          this.sendSearch()
        }
      })
    },

    // 查询设备
    sendSearchDevice() {
      request.post('deviceManage/searchByCondition', {
        queryParam: this.dialogSearchRequestParam,
        pageNum: this.dialogCurrentPage,
        pageSize: this.dialogPageSize,
      })
      .then(res => {
        if (res && res.code == 200) {
          this.dialogTableData = res.data.data
          this.dialogTotal = res.data.total
          this.dialogCurrentPage = res.data.pageNum
          this.dialogPageSize = res.data.pageSize
          // 判断是否已添加
          if (this.dialogForm.standardDeviceData.length > 0) {
            for (let i = 0; i < this.dialogTableData.length; i++) {
              if (this.dialogForm.standardDeviceData.map(i => i.id).includes(this.dialogTableData[i].id)) this.$set(this.dialogTableData[i], 'disabled', true)
            }
          }
        }
      })
      // 获取分类列表
      this.getAllType()
    },

    // 获取分类
    getAllType() {
      request.get('deviceType/getAllType').then(res => {
        if (res && res.code == 200) {
          this.categoryList = res.data
        }
      })
    },


// 数据处理
    // 计算表格高度
    getTableHeight() {
      const height = this.$refs['fullRef'].offsetHeight - this.$refs['headerRef'].offsetHeight - this.$refs['footerRef'].offsetHeight - 20
      this.tableHeight = height < 150 ? 150 : height
    },

    // 数字千分符
    // handleStandardCount(val, index) {
    //   this.$nextTick(() => {
    //     // if (this.dialogForm.standardDeviceData[index].standardCount) this.dialogForm.standardDeviceData[index].standardCount = val.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
    //     if (val) {
    //       console.log(val, index, val.toLocaleString(), this.dialogForm.standardDeviceData[index].standardCount)
    //       this.dialogForm.standardDeviceData[index].standardCount = Number(val).toLocaleString()
    //     }
    //   })
    // },

    // 根据id获取分类名字
    getCategoryName(parentId, child) {
      const parentCategory = this.categoryList.filter(e => e.value == parentId)[0]
      const childCategory = parentCategory.children.filter(e => e.value == child)[0]
      return parentCategory.label + '/' + childCategory.label
    },

  },

}
</script>

<style scoped>
.equipment-type-container {
  padding: 20px;
  height: calc(100vh - 170px);
  /* min-width: 600px; */
}
.query-form {
  margin-bottom: 20px;
}
</style>
